    // --- Pass 1: Welford online mean/variance over relu(x) ---
    float mean_acc = 0.0f;
    float m2_acc   = 0.0f;
    float count= 0.0f;

    for (int i = threadIdx.x; i < group_elems; i += BLOCK_SIZE) {
        float val = in_ptr[i];
        float r   = val > 0.0f ? val : 0.0f;
        count += 1.0f;
        float delta = r - mean_acc;
        mean_acc += delta / count;
        float delta2 = r - mean_acc;
        m2_acc += delta * delta2;
