    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            float cnt_a= s_cnt[threadIdx.x];
            float cnt_b  = s_cnt[threadIdx.x + stride];
            float mean_a = s_mean[threadIdx.x];
            float mean_b = s_mean[threadIdx.x + stride];
            float m2_a   = s_m2[threadIdx.x];
            float m2_b   = s_m2[threadIdx.x + stride];
            float cnt_ab= cnt_a + cnt_b;
            float delta   = mean_b - mean_a;
            float mean_ab = (cnt_ab > 0.0f) ? (mean_a + delta * cnt_b / cnt_ab) :0.0f;
            float m2_ab   = m2_a + m2_b + delta * delta * cnt_a * cnt_b / (cnt_ab > 0.0f ? cnt_ab : 1.0f);
            s_cnt[threadIdx.x]  = cnt_ab;
            s_mean[threadIdx.x] = mean_ab;
            s_m2[threadIdx.x]   = m2_ab;
        }
        __syncthreads();
    }

    float final_mean = s_mean[0];
    float final_var  = s_m2[0] / (float)group_elems;
    float inv_std    = rsqrtf(final_var + eps);

    // --- Pass 2: ReLU + normalize + affine with float4 vectorization ---
    int vec_elems = (group_elems / 4) * 4;

    bool aligned = ((reinterpret_cast<uintptr_t>(in_ptr) & 15) == 0) &&
                   ((reinterpret_cast<uintptr_t>(out_ptr) & 15) == 0);

    if (aligned) {
        // Vectorized loop: process 4 elements per thread per iteration
        for (int i = threadIdx.x * 4; i < vec_elems; i += BLOCK_SIZE * 4) {
            float4 v = *reinterpret_cast<const float4*>(in_ptr + i);

            float r0 = v.x > 0.0f ? v.x : 0.0f;
            float r1 = v.y > 0.0f ? v.y : 0.0f;
            float r2 = v.z > 0.0f ? v.z : 0.0f;
            float r3 = v.w > 0.0f ? v.w : 0.0f;

            int c0 = (i + 0) / spatial;
            int c1 = (i + 1) / spatial;
            int c2 = (i + 2) / spatial;
            int c3 = (i + 3) / spatial;

            float4 out_v;
            out_v.x = ((r0 - final_mean) * inv_std) * s_weight[c0] + s_bias[c0];
            out_v.y = ((r1 - final_mean) * inv_std) * s_weight[c1] + s_bias[c1];
            out_v.z = ((r2 - final_mean) * inv_std) * s_weight[c2] + s_bias[c2];
            out_v.w = ((r3 - final_mean) * inv_std) * s_weight[c3] + s_bias[c3];

            *reinterpret_cast<float4*>(out_ptr + i) = out_v;
        }
        // Scalar cleanup for any remaining elements not covered by vec_elems
        for (int i = vec_elems + threadIdx.x; i < group_elems; i += BLOCK_SIZE) {
            int c_local = i / spatial;
            float val  = in_ptr[i];
            float r    = val > 0.0f ? val : 0.0f;
            float norm = (r - final_mean) * inv_std;
            out_ptr[i] = norm * s_weight[c_local] + s_bias[c_local];
        }
