    relu_groupnorm_kernel<BLOCK><<<grid, BLOCK, smem_bytes>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        (int)num_groups,
        (float)eps
    );

    return output;
}
